-- Finance Manager-controlled per-member email request-type preferences.
-- All existing Finance Members receive all types until the Finance Manager saves a checklist.
-- The database trigger filters messages generated by either PL/pgSQL approval procedures
-- or the Node.js email services, independent of which application version is running.

create table if not exists public.finance_email_preferences (
  user_id uuid primary key references auth.users(id) on delete cascade,
  allowed_types text[] not null default '{}'::text[],
  updated_by uuid references auth.users(id) on delete set null,
  updated_at timestamptz not null default now(),
  constraint finance_email_preferences_valid_types check (
    array_position(allowed_types, null) is null
    and allowed_types <@ array[
      'trade_suppliers', 'kaliwaan_suppliers', 'supplier_payment',
      'subcon_payment', 'tpc_request', 'manpower_agency',
      'reimbursement', 'opex', 'cash_advance', 'revolving_fund', 'other'
    ]::text[]
  )
);
create index if not exists finance_email_preferences_updated_at_idx
  on public.finance_email_preferences (updated_at desc);
alter table public.finance_email_preferences enable row level security;
revoke all on public.finance_email_preferences from anon, authenticated;
grant select, insert, update, delete on public.finance_email_preferences to service_role;
comment on table public.finance_email_preferences is
  'Only Finance Head can manage through protected server API. Missing row means all request types; empty array means no Finance Member request emails.';

create or replace function public.finance_request_email_category(p_request_type text)
returns text language plpgsql immutable set search_path = ''
as $category$
declare v text := lower(btrim(coalesce(p_request_type, '')));
begin
  if v like '%revolving fund%' or v ~ '(^|[^a-z])rf([^a-z]|$)' then return 'revolving_fund'; end if;
  if v like '%cash advance%' or v ~ '(^|[^a-z])ca([^a-z]|$)' then return 'cash_advance'; end if;
  if v like '%kaliwaan%' then return 'kaliwaan_suppliers'; end if;
  if v like '%trade supplier%' then return 'trade_suppliers'; end if;
  if v like '%subcon%' then return 'subcon_payment'; end if;
  if v like '%tpc%' then return 'tpc_request'; end if;
  if v like '%manpower%' then return 'manpower_agency'; end if;
  if v like '%reimburse%' then return 'reimbursement'; end if;
  if v like '%opex%' then return 'opex'; end if;
  if v like '%supplier%' then return 'supplier_payment'; end if;
  return 'other';
end
$category$;

create or replace function public.finance_notification_allowed(
  p_recipient_email text, p_request_type text, p_template_key text
) returns boolean
language plpgsql stable set search_path = ''
as $allowed$
declare selected text[];
begin
  -- Never suppress requestor receipts, Department Head review links,
  -- Finance Head instructions, or transactional non-member notifications.
  if p_template_key not in (
    'finance_review_required', 'hard_copy_verification_required', 'liquidation_submitted'
  ) then return true; end if;

  select pref.allowed_types into selected
  from public.finance_email_preferences pref
  join public.profiles p on p.id = pref.user_id
  join public.user_roles ur on ur.user_id = pref.user_id and ur.role = 'finance_reviewer'
  where lower(p.email) = lower(btrim(coalesce(p_recipient_email, '')))
  and not exists (
    select 1 from public.user_roles head
    where head.user_id = pref.user_id and head.role = 'super_administrator'
  )
  limit 1;

  -- No explicit setting: preserve current delivery behavior.
  if not found then return true; end if;
  return public.finance_request_email_category(p_request_type) = any(selected);
end
$allowed$;

revoke all on function public.finance_request_email_category(text) from public, anon, authenticated;
revoke all on function public.finance_notification_allowed(text,text,text)
  from public, anon, authenticated;
grant execute on function public.finance_request_email_category(text) to service_role;
grant execute on function public.finance_notification_allowed(text,text,text) to service_role;

create or replace function public.filter_finance_member_email_notification()
returns trigger language plpgsql set search_path = ''
as $filter$
declare request_type text;
begin
  if new.template_key not in (
    'finance_review_required', 'hard_copy_verification_required', 'liquidation_submitted'
  ) then return new; end if;

  if new.request_id is null then return new; end if;
  select rfp_type into request_type from public.rfp_requests where id = new.request_id;
  if not found then return new; end if;

  if not public.finance_notification_allowed(
    new.recipient_email, request_type, new.template_key
  ) then
    return null; -- Quietly skip excluded Finance Member notifications.
  end if;
  return new;
end
$filter$;

drop trigger if exists finance_member_email_filter on public.email_notifications;
create trigger finance_member_email_filter
before insert or update of request_id, recipient_email, template_key
on public.email_notifications
for each row execute function public.filter_finance_member_email_notification();

revoke all on function public.filter_finance_member_email_notification()
  from public, anon, authenticated;
comment on function public.finance_notification_allowed(text,text,text) is
  'Finance Member request-category filter. Missing preference permits all. The sender also checks queued jobs before delivery.';
